import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from 'react-router-dom'; 
import "./RiverDashboard.css";

const DEBUG_API = "http://127.0.0.1:8000/api/weather/debug-read-s3";

const RiverDashboard = () => {
  const navigate = useNavigate();
  
  // --- STATE ---
  const [forecastData, setForecastData] = useState([]);
  const [limeData, setLimeData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [lastUpdated, setLastUpdated] = useState("");
  const [currentTime, setCurrentTime] = useState(new Date());

  // --- HELPERS ---
  const getStatus = (level) => {
    const val = parseFloat(level);
    if (val < 5.5) return { label: "Normal", class: "status-normal", color: "#10b981", bg: "rgba(16, 185, 129, 0.2)" }; 
    if (val < 6.0) return { label: "Caution", class: "status-caution", color: "#f59e0b", bg: "rgba(245, 158, 11, 0.2)" }; 
    return { label: "Warning", class: "status-critical", color: "#ef4444", bg: "rgba(239, 68, 68, 0.2)" }; 
  };

  // --- EFFECTS ---
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const fetchForecast = async () => {
      try {
        const response = await axios.get(DEBUG_API, { params: { file: "forecast_output.csv" } });
        if (response.data.status === "success") {
          const rawLines = response.data.preview;
          const parsedData = rawLines.slice(1).map((line) => {
              const cols = line.split(",");
              const level = cols[cols.length - 1]?.trim();
              return { level: parseFloat(level).toFixed(2), status: getStatus(level) };
            }).filter((item) => !isNaN(item.level));
          setForecastData(parsedData);
          setLastUpdated(new Date().toLocaleTimeString("en-US", {hour: '2-digit', minute:'2-digit'}));
        }
      } catch (err) {
        console.error("Forecast API error:", err);
        setError("Failed to fetch forecast data");
      }
    };

    const fetchLimeInsights = async () => {
      try {
        const response = await axios.get(DEBUG_API, { params: { file: "lime_short_sentences_and_labels.txt" } });
        if (response.data.status === "success") {
          setLimeData(response.data.preview);
        }
      } catch (err) {
        console.error("LIME API error:", err);
      }
    };

    const loadAllData = async () => {
      setLoading(true);
      await Promise.all([fetchForecast(), fetchLimeInsights()]);
      setLoading(false);
    };

    loadAllData();
  }, []);

  // --- RENDER VARS ---
  const nextHour = forecastData[0] || { level: "--", status: getStatus(0) };
  const currentLevel = (parseFloat(nextHour.level) - 0.17).toFixed(2);
  const currentStatus = getStatus(currentLevel);

  if (loading) return (
    <div className="rd-loading-screen">
      <div className="loader"></div>
      <h3>Initializing Satellite Link...</h3>
    </div>
  );

  return (
    <div className="rd-container">
      
      {/* BACKGROUND ELEMENTS */}
      <div className="rd-bg-glow"></div>

      {/* --- HEADER --- */}
      <header className="rd-header">
        <div className="rd-wrapper rd-flex-between">
          <div className="rd-brand">
            <div className="brand-logo"><i className="fas fa-water"></i></div>
            <div className="brand-text">
              <h2>Periyar<span>Watch</span></h2>
              <small>MeitY & ASIET Initiative</small>
            </div>
          </div>
          <nav className="rd-nav">
            <button onClick={() => navigate('/')}>Home</button>
            <button className="active">Live Dashboard</button>
            <button onClick={() => navigate('/weather-map')}>Map View</button>
          </nav>
        </div>
      </header>

      {/* --- MAIN DASHBOARD CONTENT --- */}
      <main className="rd-wrapper rd-main">
        
        {/* ROW 1: STATUS HERO & KPIS */}
        <section className="rd-hero-grid">
          
          {/* Main Status Card */}
          <div className={`rd-card hero-card ${currentStatus.class}`}>
            <div className="hero-content">
              <span className="pill">Kalady Station • Live</span>
              <h1>{currentLevel}<span>m</span></h1>
              <p>Current Water Level</p>
            </div>
            <div className="hero-icon">
              <i className={currentStatus.class === 'status-normal' ? "fas fa-shield-alt" : "fas fa-exclamation-triangle"}></i>
              <span>{currentStatus.label}</span>
            </div>
          </div>

          {/* KPI: Next Hour */}
          <div className="rd-card kpi-card">
            <div className="card-label">
              <i className="fas fa-clock"></i> Forecast (+1 Hr)
            </div>
            <div className="kpi-value" style={{color: nextHour.status.color}}>
              {nextHour.level}m
            </div>
            <div className="kpi-sub">
              Prediction Confidence: 98%
            </div>
          </div>

          {/* KPI: Time & Sync */}
          <div className="rd-card kpi-card">
            <div className="card-label">
              <i className="fas fa-sync-alt"></i> Last Sync
            </div>
            <div className="kpi-value time">
              {lastUpdated}
            </div>
            <div className="kpi-sub">
              {currentTime.toLocaleDateString()}
            </div>
          </div>
        </section>

        {/* ROW 2: 6-HOUR PROJECTION CHART */}
        <section className="rd-section full-width">
          <div className="sec-title">
            <h3><i className="fas fa-chart-bar"></i> 6-Hour Water Level Projection</h3>
          </div>
          <div className="rd-chart-container">
            {forecastData.slice(0, 6).map((data, index) => (
              <div key={index} className="chart-col">
                <div className="bar-wrapper">
                  <div 
                    className="bar-fill" 
                    style={{
                      height: `${Math.min((data.level / 8) * 100, 100)}%`,
                      background: `linear-gradient(to top, ${data.status.color}, ${data.status.color}88)`
                    }}
                  >
                    <span className="bar-tooltip">{data.level}m</span>
                  </div>
                </div>
                <div className="col-label">
                  <span className="hour">+{index + 1}H</span>
                  <span className="status-dot" style={{background: data.status.color}}></span>
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* ROW 3: EXPLAINABLE AI (FULL WIDTH & GRID) */}
        <section className="rd-section full-width">
          <div className="sec-title">
            <h3><i className="fas fa-brain"></i> AI Explainability & Insights (LIME)</h3>
            <span className="badge-ai">Analysis Mode: Deep</span>
          </div>
          
          <div className="rd-ai-grid">
            {limeData.length > 0 ? (
              limeData.slice(0, 6).map((line, index) => {
                const statusColor = forecastData[index]?.status?.color || "#3b82f6";
                return (
                  <div key={index} className="rd-ai-card">
                    <div className="ai-header">
                      <div className="ai-badge" style={{background: statusColor}}>
                        Hour +{index+1}
                      </div>
                      <i className="fas fa-microchip" style={{color: statusColor}}></i>
                    </div>
                    <p className="ai-text">{line}</p>
                  </div>
                );
              })
            ) : (
              <div className="empty-msg">Waiting for interpretation stream...</div>
            )}
          </div>
        </section>

      </main>

      <footer className="rd-footer">
        <p>© 2026 Intelligent River Monitoring System • Designed for ASIET</p>
      </footer>
    </div>
  );
};

export default RiverDashboard;
